const META_POOL = [
  '오늘 · 방문자 리뷰',
  '어제 · 방문자 리뷰',
  '2일 전 · 방문자 리뷰',
  '3일 전 · 방문자 리뷰',
  '4일 전 · 방문자 리뷰',
  '5일 전 · 방문자 리뷰',
  '6일 전 · 방문자 리뷰',
  '1주 전 · 방문자 리뷰',
  '2주 전 · 방문자 리뷰',
  '3주 전 · 방문자 리뷰',
  '한 달 전 · 방문자 리뷰',
];

// 실제 날짜 데이터가 없으므로 인덱스 기반으로 그럴듯한 상대 날짜를 부여한다
export const REVIEWS = RAW_REVIEWS.map(([text, category, tone], i) => ({
  id: `review-${i}`,
  text,
  categories: [category],
  tone,
  meta: META_POOL[(i * 7 + 3) % META_POOL.length],
  isUserSubmitted: false,
}));

export function reviewsByCategory(category) {
  return REVIEWS.filter((r) => r.categories.includes(category));
}

let userReviewCounter = 0;

// "내 리뷰 추가하기"로 등록한 리뷰를 즉시 REVIEWS 풀에 반영한다(별도 배치를 기다리지 않음).
export function addUserReview({ text, categories, tone }) {
  userReviewCounter += 1;
  const review = {
    id: `user-review-${userReviewCounter}`,
    text,
    categories,
    tone,
    meta: '방금 전 · 내가 등록',
    isUserSubmitted: true,
  };
  REVIEWS.push(review);
  return review;
}
